unsigned process_audio_data(SF_PRIVATE* psf, unsigned len) {
    unsigned bytes_read = 0;
    unsigned remaining = len;
    unsigned buffer_pos = 0;

    if (psf == NULL || len == 0) {
        return 0;
    }

    if (psf->frame.buffer != NULL && psf->frame.buffered > 0) {
        unsigned copy_len = psf->frame.buffered;
        if (copy_len > remaining) {
            copy_len = remaining;
        }
        memcpy(psf->output + bytes_read, psf->frame.buffer + buffer_pos, copy_len);
        bytes_read += copy_len;
        buffer_pos += copy_len;
        psf->frame.buffered -= copy_len;
        remaining -= copy_len;
    }

    while (remaining > 0 && !psf->eof_reached) {
        unsigned decoded = decode_audio_frame(psf, psf->output + bytes_read, remaining);
        if (decoded == 0) {
            break;
        }
        bytes_read += decoded;
        remaining -= decoded;
    }

    return bytes_read;
}
